mapper.select:
/* voteBoard */

SELECT *
FROM board_vote
WHERE
    board_id = #{board_id} AND
    user_id = #{user_id}

mapper.insert:
/* createVote */

INSERT INTO board_vote (
    board_id,
    user_id,
    vote_type
) VALUES (
    #{board_id},
    #{user_id},
    #{vote_type}
)

mapper.update:
/* updateVote */

UPDATE board_vote
SET vote_type = #{vote_type}
WHERE
    board_id = #{board_id} AND
    user_id = #{user_id}

mapper.delete:
/* deleteVote */

DELETE FROM board_vote
WHERE
    board_id = #{board_id} AND
    user_id = #{user_id} AND
    vote_type = #{vote_type}

mapper.select:
/* getVoteStatus */

SELECT vote_type
FROM board_vote
WHERE
    board_id = #{board_id} AND
    user_id = #{user_id}

/* getVoteCount */

SELECT
    COUNT(CASE WHEN vote_type = 'UP' THEN 1 END) AS upCnt,
    COUNT(CASE WHEN vote_type = 'DOWN' THEN 1 END) AS downCnt
FROM board_vote
WHERE board_id = #{boardId}
